"  useEffect(() => {
    if (isAuthenticated) initApp();
  }, [isAuthenticated]);

  useEffect(() => {
    if (!isAuthenticated) return;

    const silentSync = async () => {
      // 1. Fetch CRM Customers silently in background
      try {
        const custRes = await posService.getCustomers();
        if (custRes.data && Array.isArray(custRes.data)) {
          const customersMap = {};
          custRes.data.forEach(c => {
            customersMap[c.phone] = {
              name: c.name,
              phone: c.phone,
              address: c.address,
              points: Number(c.points) || 0,
              orders: Number(c.orders) || 0,
              totalSpent: Number(c.total_spent) || 0,
              balance: Number(c.balance) || 0
            };
          });
          setCustomerDb(prev => {
            if (JSON.stringify(prev) !== JSON.stringify(customersMap)) {
              localStorage.setItem('pos_customer_db', JSON.stringify(customersMap));
              return customersMap;
            }
            return prev;
          });
        }
      } catch (e) {
        console.warn("Background sync - Failed to load customers:", e);
      }

      // 2. Fetch Orders silently in background
      try {
        await fetchOrdersForMode(receiptsDateMode);
      } catch (err) {
        console.warn("Background sync - Failed to load orders:", err);
      }
    };

    const syncInterval = setInterval(silentSync, 10000); // Poll every 10 seconds
    return () => clearInterval(syncInterval);
  }, [isAuthenticated, receiptsDateMode]);"
